// ─── Core ───────────────────────────────────────────────────────────────────
export * from './core/agent-loop.js';
export * from './core/auth.js';
export * from './core/config.js';
export * from './core/harness-factory.js';
export * from './core/profile.js';
export * from './core/session-history.js';
export * from './core/structured-output.js';
export * from './core/types.js';
export * from './core/utils.js';
export * from './core/workflow-loader.js';
export * from './setup.js';

// ─── Tracking ───────────────────────────────────────────────────────────────
export * from './tracking/audit-log.js';
export * from './tracking/task-status.js';
export * from './tracking/workflow-status.js';

// ─── Pool ────────────────────────────────────────────────────────────────
export * from './pool/index.js';

import { readdir, stat } from 'node:fs/promises';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { resolveWorkflowsDirs } from './config.js';
import type { WorkflowEntry, WorkflowModule } from './types.js';
import { validateWorkflowName } from './utils.js';

// ─── Cache ──────────────────────────────────────────────────────────────────

const workflowCache = new Map<string, WorkflowModule>();

/** Clears the module-level workflow cache. */
export function clearWorkflowCache(): void {
  workflowCache.clear();
}

// ─── loadWorkflow ───────────────────────────────────────────────────────────

/**
 * Dynamically loads a workflow module by name, searching local then global
 * workflow directories. Caches loaded modules by resolved absolute file path.
 */
export async function loadWorkflow(name: string, cwd: string): Promise<WorkflowModule> {
  // Validate workflow name to prevent path traversal
  validateWorkflowName(name);

  const dirs = resolveWorkflowsDirs(cwd);

  for (const dir of dirs) {
    const filePath = join(dir, name, 'main.ts');

    try {
      const fileStat = await stat(filePath);
      if (!fileStat.isFile()) continue;
    } catch {
      continue;
    }

    // Check cache first
    const cached = workflowCache.get(filePath);
    if (cached) return cached;

    const mod = await import(pathToFileURL(filePath).href);
    const workflow: WorkflowModule = mod.default ?? mod;

    if (typeof workflow.run !== 'function') {
      throw new Error(`Workflow '${name}' does not export a 'run' function.`);
    }

    workflowCache.set(filePath, workflow);
    return workflow;
  }

  throw new Error(`Workflow '${name}' not found.`);
}

// ─── listWorkflows ──────────────────────────────────────────────────────────

/**
 * Lists available workflow files across local and global directories.
 * Returns entries sorted by name, then by source (local first).
 */
export async function listWorkflows(cwd: string): Promise<WorkflowEntry[]> {
  const dirs = resolveWorkflowsDirs(cwd);
  const dirEntries: { dir: string; source: 'local' | 'global' }[] = [
    { dir: dirs[0], source: 'local' },
    { dir: dirs[1], source: 'global' },
  ];
  const results: WorkflowEntry[] = [];

  for (const { dir, source } of dirEntries) {
    let entries: string[];
    try {
      entries = await readdir(dir);
    } catch {
      // Directory does not exist — skip
      continue;
    }

    for (const entry of entries) {
      // Skip hidden directories
      if (entry.startsWith('.')) continue;

      const entryPath = join(dir, entry);

      // Only include directories
      try {
        const entryStat = await stat(entryPath);
        if (!entryStat.isDirectory()) continue;
      } catch {
        continue;
      }

      // Check that main.ts exists inside the directory
      const mainPath = join(entryPath, 'main.ts');
      try {
        const mainStat = await stat(mainPath);
        if (!mainStat.isFile()) continue;
      } catch {
        continue;
      }

      results.push({ name: entry, source, path: mainPath });
    }
  }

  // Sort by name, then by source (local first)
  results.sort((a, b) => {
    const nameCmp = a.name.localeCompare(b.name);
    if (nameCmp !== 0) return nameCmp;
    // local before global
    if (a.source === b.source) return 0;
    return a.source === 'local' ? -1 : 1;
  });

  return results;
}

// ─── Harness Factory ────────────────────────────────────────────────────────
import { getModel } from '@earendil-works/pi-ai';
import type { AgentSession } from '@earendil-works/pi-coding-agent';
import {
  type AgentSessionEvent,
  AuthStorage,
  createAgentSession,
  DefaultResourceLoader,
  SessionManager,
} from '@earendil-works/pi-coding-agent';

import { loadProfile } from './profile.js';
import type { HarnessCreationOptions, TurnContentBlock } from './types.js';
import { DEFAULT_TOOLS } from './utils.js';

// ─── Agent Event Types ──────────────────────────────────────────────────────

/* eslint-disable @typescript-eslint/no-explicit-any */
type AgentLevelEvent =
  | { type: 'turn_start' }
  | { type: 'turn_end'; message: { role: string; content?: any[]; usage?: { input: number; output: number } } }
  | { type: 'tool_execution_start'; toolName: string; toolCallId: string; args?: Record<string, unknown> }
  | { type: 'tool_execution_end'; toolName: string; toolCallId: string; isError: boolean };
/* eslint-enable @typescript-eslint/no-explicit-any */

// ─── createHarness ──────────────────────────────────────────────────────────

/**
 * Create an {@link AgentSession} wired to an in-memory session.
 *
 * Resolution steps:
 * 1. Resolve the model via {@link getModel}; throw if the provider/model
 *    combination is unknown.
 * 2. Create an {@link AuthStorage} via {@link AuthStorage.create} (loads
 *    credentials from `~/.pi/agent/auth.json`) and apply any caller-supplied
 *    `apiKeys` as runtime overrides.
 * 3. Build the tool allowlist/denylist from the profile configuration.
 * 4. Create a {@link DefaultResourceLoader} with the profile's system prompt.
 * 5. Construct the session via {@link createAgentSession}.
 * 6. Optionally subscribe to agent status callbacks.
 */
export async function createHarness(
  options: HarnessCreationOptions,
): Promise<{ session: AgentSession; sessionId: string; dispose: () => void }> {
  const { profile, cwd, apiKeys, onAgentStatus } = options;

  // 1. Model
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const model = getModel(profile.provider as any, profile.model as any);
  if (!model) {
    throw new Error(
      `Unknown model "${profile.model}" for provider "${profile.provider}". ` +
        `Check the provider and model identifiers.`,
    );
  }

  // 2. Auth storage — reads ~/.pi/agent/auth.json for stored credentials
  const authStorage = AuthStorage.create();
  if (apiKeys) {
    for (const [provider, key] of Object.entries(apiKeys)) {
      authStorage.setRuntimeApiKey(provider, key);
    }
  }

  // 3. Tools
  let builtTools: string[];
  if (profile.includeTools && profile.includeTools.length > 0) {
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    builtTools = [...DEFAULT_TOOLS].filter((name) => profile.includeTools!.includes(name));
  } else {
    builtTools = [...DEFAULT_TOOLS];
  }
  if (profile.excludeTools && profile.excludeTools.length > 0) {
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    builtTools = builtTools.filter((name) => !profile.excludeTools!.includes(name));
  }

  // 4. Resource loader
  const resourceLoader = new DefaultResourceLoader({
    cwd,
    agentDir: cwd,
    systemPromptOverride: () => profile.systemPrompt,
  });
  await resourceLoader.reload();

  // 5. Session
  let sessionManager;
  if (options.resumeSessionPath) {
    sessionManager = SessionManager.open(options.resumeSessionPath, undefined, cwd);
  } else if (options.sessionDir) {
    sessionManager = SessionManager.create(cwd, options.sessionDir);
  } else {
    sessionManager = SessionManager.inMemory(cwd);
  }
  const { session } = await createAgentSession({
    sessionManager,
    model,
    thinkingLevel: profile.thinkingLevel,
    tools: builtTools,
    resourceLoader,
    authStorage,
  });

  const sessionId = session.sessionId;

  // 6. Subscribe to agent status callbacks (if any handlers provided)
  let unsubscribe: (() => void) | undefined;
  if (
    onAgentStatus &&
    (onAgentStatus.onTurnStart ||
      onAgentStatus.onTurnEnd ||
      onAgentStatus.onToolCallStart ||
      onAgentStatus.onToolCallEnd)
  ) {
    let turnCount = 0;
    unsubscribe = session.subscribe((event: AgentSessionEvent) => {
      const e = event as AgentLevelEvent;
      if (e.type === 'turn_start') {
        onAgentStatus.onTurnStart?.({
          agentId: sessionId,
          turn: ++turnCount,
        });
      } else if (e.type === 'turn_end') {
        const isAssistant = e.message?.role === 'assistant';
        const usage = isAssistant ? e.message?.usage : undefined;
        let contentBlocks: TurnContentBlock[] | undefined;
        if (isAssistant && e.message.content) {
          contentBlocks = [];
          // Map only the block types supported by TurnContentBlock.
          // Unrecognized types (e.g., future upstream additions) are intentionally skipped.
          for (const block of e.message.content) {
            if (block.type === 'text') {
              contentBlocks.push({ type: 'text', text: block.text });
            } else if (block.type === 'thinking') {
              contentBlocks.push({ type: 'thinking', thinking: block.thinking, redacted: block.redacted });
            } else if (block.type === 'toolCall') {
              contentBlocks.push({ type: 'toolCall', id: block.id, name: block.name, arguments: block.arguments });
            }
          }
        }
        onAgentStatus.onTurnEnd?.({
          agentId: sessionId,
          turn: turnCount,
          tokens: usage ? { input: usage.input, output: usage.output } : undefined,
          contentBlocks,
        });
      } else if (e.type === 'tool_execution_start') {
        onAgentStatus.onToolCallStart?.({
          agentId: sessionId,
          toolName: e.toolName,
          toolCallId: e.toolCallId,
          arguments: e.args ?? {},
        });
      } else if (e.type === 'tool_execution_end') {
        onAgentStatus.onToolCallEnd?.({
          agentId: sessionId,
          toolName: e.toolName,
          toolCallId: e.toolCallId,
          isError: e.isError ?? false,
        });
      }
    });
  }

  const dispose = () => {
    unsubscribe?.();
    session.dispose();
  };

  return { session, sessionId, dispose };
}

// ─── createHarnessFromProfile ───────────────────────────────────────────────

/**
 * Convenience wrapper that loads an {@link AgentProfile} from a directory
 * and delegates to {@link createHarness}.
 */
export async function createHarnessFromProfile(
  dirPath: string,
  profileId: string,
  options: Omit<HarnessCreationOptions, 'profile'>,
): Promise<{ session: AgentSession; sessionId: string; dispose: () => void }> {
  const profile = await loadProfile(dirPath, profileId);
  return createHarness({ ...options, profile });
}

