// ─── Re-exports from @earendil-works/pi-coding-agent ───────────────────────
export { AgentSession, AuthStorage, DefaultResourceLoader, SessionManager } from '@earendil-works/pi-coding-agent';
export type { ThinkingLevel };

// ─── Peer dependency re-exports (not re-exported by pi-coding-agent) ───────
import type { ThinkingLevel } from '@earendil-works/pi-agent-core';

export { getModel, parseJsonWithRepair } from '@earendil-works/pi-ai';
export type { Model } from '@earendil-works/pi-ai';

// ─── Agent Profile ──────────────────────────────────────────────────────────
export interface AgentProfile {
  id: string;
  name: string;
  provider: string;
  model: string;
  thinkingLevel: ThinkingLevel;
  systemPrompt: string;
  excludeTools: string[];
  includeTools: string[];
}

// ─── Task Tracking ──────────────────────────────────────────────────────────
export type TaskStatus = 'blocked' | 'ready' | 'claimed' | 'implementing' | 'reviewing' | 'done';

export interface Task {
  id: string;
  title: string;
  prompt: string;
  profile: string;
  files: string[];
  dependencies: string[];
  status: TaskStatus;
  assignedAgent?: string;
  result?: unknown;
  reviewFeedback?: string;
  isCode?: boolean;
}

// ─── Workflow Phases ────────────────────────────────────────────────────────
export type WorkflowPhase =
  | 'scouting'
  | 'scouting_review'
  | 'planning'
  | 'plan_review'
  | 'implementing'
  | 'final_review'
  | 'done';

export interface WorkflowState {
  taskPrompt: string;
  currentPhase: WorkflowPhase;
  completedPhases: WorkflowPhase[];
  tasks: Task[];
  /** Scouting reports stored as opaque values; consumers should cast to their specific schema type */
  scoutingReports: unknown[];
  /** Plan stored as opaque value; consumers should cast to their specific schema type */
  plan: unknown;
  research?: string;
  /** Plan review feedback text from the reviewer when a plan is rejected */
  planReviewFeedback?: string;
  /** Specific improvement suggestions from the plan reviewer */
  planReviewSuggestions?: string[];
  stats: {
    totalTokens: number;
    totalCost: number;
    agentCount: number;
  };
}

// ─── Audit Events ───────────────────────────────────────────────────────────
export type AuditEvent =
  | { type: 'agent_start'; agentId: string; profile: AgentProfile; taskId?: string; timestamp: string }
  | { type: 'agent_end'; agentId: string; result: unknown; taskId?: string; timestamp: string }
  | { type: 'decision'; agentId: string; decision: string; reasoning: string; taskId?: string; timestamp: string }
  | { type: 'structured_output'; agentId: string; output: unknown; taskId?: string; timestamp: string }
  | { type: 'error'; agentId: string; error: string; taskId?: string; timestamp: string };

// ─── Structured Output ──────────────────────────────────────────────────────
export interface StructuredOutputOptions {
  maxRetries: number;
  retryPrompt?: string;
}

// ─── Status Callbacks ──────────────────────────────────────────────────────
export interface WorkflowStatusCallbacks {
  onWorkflowStart?: (info: { taskPrompt: string; resumed: boolean; workDir: string }) => void;
  onPhaseStart?: (info: { phase: string; round: number }) => void;
  onPhaseComplete?: (info: { phase: string; durationMs: number }) => void;
  onAgentSpawn?: (info: { agentId: string; profile: string; phase: string; taskId?: string }) => void;
  onAgentComplete?: (info: { agentId: string; profile: string; phase: string; taskId?: string }) => void;
  onTaskStart?: (info: { taskId: string; title: string; agentId: string }) => void;
  onTaskComplete?: (info: { taskId: string; title: string }) => void;
  onTaskRejected?: (info: { taskId: string; title: string; reason: string }) => void;
  onDecision?: (info: { agentId: string; decision: string; reasoning: string; taskId?: string }) => void;
  onError?: (info: { agentId: string; error: string; phase: string; taskId?: string }) => void;
  onWorkflowComplete?: (info: { totalDurationMs: number; agentCount: number }) => void;
  onWorkflowFailed?: (info: { error: Error; phase: string }) => void;
  onSidebarUpdate?: (info: { title?: string; indicator?: string; phases?: Array<{ id: string; label: string; icon: string }> }) => void;
}

export type TurnContentBlock =
  | { type: 'text'; text: string }
  | { type: 'thinking'; thinking: string; redacted?: boolean }
  | { type: 'toolCall'; id: string; name: string; arguments: Record<string, unknown> };

export interface AgentStatusCallbacks {
  onTurnStart?: (info: { agentId: string; turn: number }) => void;
  onTurnEnd?: (info: {
    agentId: string;
    turn: number;
    tokens?: { input: number; output: number };
    contentBlocks?: TurnContentBlock[];
  }) => void;
  onToolCallStart?: (info: { agentId: string; toolName: string; toolCallId: string; arguments: Record<string, unknown> }) => void;
  onToolCallEnd?: (info: { agentId: string; toolName: string; toolCallId: string; isError: boolean }) => void;
}

export type StatusCallbacks = WorkflowStatusCallbacks & AgentStatusCallbacks;

// ─── Agent Loop Result ──────────────────────────────────────────────────────
export interface AgentLoopResult<T> {
  result: T;
  attempts: number;
  totalTokens: { input: number; output: number };
}

// ─── Workflow Run Options ──────────────────────────────────────────────────
export interface WorkflowRunOptions {
  cwd: string;
  workDir: string;
  maxConcurrentTasks?: number;
  apiKeys?: Record<string, string>;
  onStatus?: StatusCallbacks;
  /** Abort signal for cooperative cancellation (e.g. SIGINT) */
  signal?: AbortSignal;
}

// ─── Workflow Entry ───────────────────────────────────────────────────────
export interface WorkflowEntry {
  name: string;
  source: 'local' | 'global';
  path: string;
}

// ─── Workflow Module ────────────────────────────────────────────────────────
export interface WorkflowModule {
  run(taskPrompt: string, options: WorkflowRunOptions): Promise<void>;
  name?: string;
  description?: string;
}

// ─── Harness Creation ───────────────────────────────────────────────────────
export interface HarnessCreationOptions {
  profile: AgentProfile;
  cwd: string;
  apiKeys?: Record<string, string>;
  onAgentStatus?: AgentStatusCallbacks;
  sessionDir?: string;
  resumeSessionPath?: string;
}

import { parse } from 'dotenv';
import { readFileSync } from 'node:fs';
import { mkdir } from 'node:fs/promises';
import { homedir } from 'node:os';
import { join } from 'node:path';
import { isEnoentError, validateWorkflowName } from './utils.js';

/**
 * Returns the global configuration directory for engin.
 * Uses $XDG_CONFIG_HOME/engin if XDG_CONFIG_HOME is set and non-empty,
 * otherwise falls back to ~/.config/engin.
 */
export function getGlobalConfigDir(): string {
  const xdg = process.env.XDG_CONFIG_HOME;
  if (xdg && xdg.length > 0) {
    return join(xdg, 'engin');
  }
  return join(homedir(), '.config', 'engin');
}

/**
 * Returns the local (project-level) configuration directory for engin.
 */
export function getLocalConfigDir(cwd: string): string {
  return join(cwd, '.engin');
}

/**
 * Returns profile directories in override-priority order (local first).
 * Does NOT check whether the directories exist.
 *
 * When `workflowName` is a non-empty string, returns workflow-scoped
 * profile directories under `workflows/<workflowName>/profiles`.
 * When `workflowName` is omitted or empty, returns an empty array.
 */
export function resolveProfilesDirs(cwd: string, workflowName?: string): string[] {
  if (!workflowName || workflowName.length === 0) {
    return [];
  }
  validateWorkflowName(workflowName);
  return [
    join(getLocalConfigDir(cwd), 'workflows', workflowName, 'profiles'),
    join(getGlobalConfigDir(), 'workflows', workflowName, 'profiles'),
  ];
}

/**
 * Returns workflow directories in override-priority order (local first).
 * Does NOT check whether the directories exist.
 */
export function resolveWorkflowsDirs(cwd: string): string[] {
  return [join(getLocalConfigDir(cwd), 'workflows'), join(getGlobalConfigDir(), 'workflows')];
}

/**
 * Returns the default working directory for a named workflow.
 */
export function getDefaultWorkDir(cwd: string, workflowName: string): string {
  return join(getLocalConfigDir(cwd), 'work', workflowName);
}

/**
 * Recursively creates a directory. Re-throws any errors.
 */
export async function ensureDir(dirPath: string): Promise<void> {
  await mkdir(dirPath, { recursive: true });
}

/**
 * Result of loading .env files from global and local config directories.
 */
export interface LoadEnvResult {
  loadedFiles: string[]; // paths of .env files that existed and were parsed
  skippedFiles: string[]; // paths of .env files that did not exist
  keysSet: string[]; // env var names actually written to process.env (excluding already-set keys)
}

/** Environment variable names that are never loaded from .env files due to security risks. */
const BLOCKED_ENV_KEYS = new Set([
  'NODE_OPTIONS',
  'NODE_TLS_REJECT_UNAUTHORIZED',
  'NODE_EXTRA_CA_CERTS',
  'LD_PRELOAD',
  'LD_LIBRARY_PATH',
  'PATH',
  'HOME',
  'SHELL',
]);

/**
 * Loads .env files from global and local config directories, merges them
 * (local overrides global), and sets keys into process.env only if they are
 * not already defined.
 *
 * Synchronous because .env loading must complete before any command dispatch.
 */
export function loadEnvFiles(cwd: string): LoadEnvResult {
  const globalEnvPath = join(getGlobalConfigDir(), '.env');
  const localEnvPath = join(getLocalConfigDir(cwd), '.env');

  const loadedFiles: string[] = [];
  const skippedFiles: string[] = [];
  let globalVars: Record<string, string> = {};
  let localVars: Record<string, string> = {};

  for (const envPath of [globalEnvPath, localEnvPath]) {
    try {
      const content = readFileSync(envPath, 'utf-8');
      const parsed = parse(content);
      loadedFiles.push(envPath);
      if (envPath === globalEnvPath) {
        globalVars = parsed;
      } else {
        localVars = parsed;
      }
    } catch (err: unknown) {
      if (isEnoentError(err)) {
        skippedFiles.push(envPath);
      } else {
        throw err;
      }
    }
  }

  const merged = { ...globalVars, ...localVars };
  const keysSet: string[] = [];

  for (const [key, value] of Object.entries(merged)) {
    if (BLOCKED_ENV_KEYS.has(key)) {
      continue;
    }
    if (!(key in process.env)) {
      process.env[key] = value;
      keysSet.push(key);
    }
  }

  return { loadedFiles, skippedFiles, keysSet };
}

