import { useTempDir } from '../helpers/use-temp-dir.js';

// ─── Temp directory helper ──────────────────────────────────────────────────

const { getDir } = useTempDir();

let localWorkflowDir: string;
let savedXdg: string | undefined;
let savedApiKeys: Record<string, string> | undefined;

beforeEach(async () => {
  savedXdg = process.env.XDG_CONFIG_HOME;
  savedApiKeys = process.env.ANTHROPIC_API_KEY ? { anthropic: process.env.ANTHROPIC_API_KEY } : undefined;
  localWorkflowDir = join(getDir(), 'local', '.engin', 'workflows');
  await mkdir(localWorkflowDir, { recursive: true });
  clearWorkflowCache();
});

afterEach(() => {
  if (savedXdg === undefined) {
    delete process.env.XDG_CONFIG_HOME;
  } else {
    process.env.XDG_CONFIG_HOME = savedXdg;
  }
});

function makeCwd(): string {
  process.env.XDG_CONFIG_HOME = join(getDir(), 'global');
  return join(getDir(), 'local');
}

/**
 * Helper: copy the develop workflow main.ts into the temp workflows directory.
 */
async function setupDevelopWorkflow(): Promise<void> {
  const srcPath = join(import.meta.dirname, '..', '..', '.engin', 'workflows', 'develop', 'main.ts');
  const destDir = join(localWorkflowDir, 'develop');
  await mkdir(destDir, { recursive: true });

  // Read and write the file content
  const content = await Bun.file(srcPath).text();
  await writeFile(join(destDir, 'main.ts'), content);
}

